import torch
from clharness.train.hooks import BaseHook

class TokenRowNormHook(BaseHook):
    @torch.no_grad()
    def on_run_start(self, ctx):
        self.tables = []
        modules = [ctx.model.get_input_embeddings(), ctx.model.get_output_embeddings()]
        for module in modules:
            if module is not None:
                p = module.weight
                duplicate = any(p is entry[0] for entry in self.tables)
                if p.ndim == 2 and not duplicate:
                    pieces = []
                    for start in range(0, p.shape[0], 4096):
                        pieces.append(p[start:start + 4096].float().norm(dim=1))
                    self.tables.append((p, torch.cat(pieces)))

    @torch.no_grad()
    def on_step_end(self, ctx, stats):
        for p, target in self.tables:
            for start in range(0, p.shape[0], 4096):
                block = p[start:start + 4096]
                current = block.float().norm(dim=1).clamp_min(1e-12)
                scale = target[start:start + 4096] / current
                block.mul_(scale.to(dtype=block.dtype).unsqueeze(1))

import torch
from clharness.train.hooks import BaseHook

class FreezeNormCalibration(BaseHook):
    def configure_model(self, ctx):
        for name, module in ctx.model.named_modules():
            if 'norm' in name.lower() or isinstance(module, torch.nn.LayerNorm):
                for parameter in module.parameters(recurse=False):
                    if parameter.ndim <= 1:
                        parameter.requires_grad_(False)
        return None
